import{_ as t,o as r,c as a,a2 as l}from"./chunks/framework.Bx7X8BVG.js";const f=JSON.parse('{"title":"Cloudflare 免费版：限制、来源与使用建议","description":"","frontmatter":{},"headers":[],"relativePath":"guide/limits.md","filePath":"guide/limits.md","lastUpdated":null}'),d={name:"guide/limits.md"};function n(o,e,s,u,c,i){return r(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="cloudflare-免费版-限制、来源与使用建议" tabindex="-1">Cloudflare 免费版：限制、来源与使用建议 <a class="header-anchor" href="#cloudflare-免费版-限制、来源与使用建议" aria-label="Permalink to &quot;Cloudflare 免费版：限制、来源与使用建议&quot;">​</a></h1><p>核对日期：<strong>2026-10-07</strong>。这是 Cloudflare 服务限制，不是本项目给用户设置的收费或额度。实际配置以 Cloudflare 账户后台及当前官方条款为准。</p><h2 id="正式-tunnel-与临时-quick-tunnel" tabindex="-1">正式 Tunnel 与临时 Quick Tunnel <a class="header-anchor" href="#正式-tunnel-与临时-quick-tunnel" aria-label="Permalink to &quot;正式 Tunnel 与临时 Quick Tunnel&quot;">​</a></h2><p>本面板通过 Cloudflare 账户创建<strong>命名隧道</strong>，通常绑定你的域名。免费的 <code>trycloudflare.com</code> 临时地址属于 Quick Tunnel，不能把它的限制套用到命名隧道。</p><table tabindex="0"><thead><tr><th>类型</th><th>规则</th><th>官方依据</th></tr></thead><tbody><tr><td>命名隧道</td><td>每账户最多 1,000 条 cloudflared 隧道</td><td><a href="https://developers.cloudflare.com/cloudflare-one/account-limits/#cloudflare-tunnel" target="_blank" rel="noreferrer">账户限额</a></td></tr><tr><td>命名隧道副本</td><td>每隧道最多 25 个活跃 cloudflared 副本；不是 25 位访客</td><td>同上</td></tr><tr><td>私网路由</td><td>每账户 1,000 条 CIDR + Hostname route，与 Mesh 共享；不是直接说只能配 1,000 个公开子域名</td><td>同上</td></tr><tr><td>Quick Tunnel</td><td>最多 200 个同时处理中请求，超出返回 429</td><td><a href="https://developers.cloudflare.com/tunnel/get-started/quick-tunnels/#limitations" target="_blank" rel="noreferrer">Quick Tunnel 限制</a></td></tr><tr><td>Quick Tunnel</td><td>不支持 SSE、无 uptime 保证，重建后域名变化</td><td>同上</td></tr></tbody></table><h2 id="http-上传与缓存" tabindex="-1">HTTP 上传与缓存 <a class="header-anchor" href="#http-上传与缓存" aria-label="Permalink to &quot;HTTP 上传与缓存&quot;">​</a></h2><p>通过 Cloudflare 公网反向代理域名访问，受域名套餐限制：</p><table tabindex="0"><thead><tr><th>项目</th><th>Free</th><th>Pro</th><th>Business</th><th>Enterprise</th></tr></thead><tbody><tr><td>单次 HTTP 上传</td><td>100 MB</td><td>100 MB</td><td>200 MB</td><td>最高 5 GB；更大需额外配置</td></tr><tr><td>单个可缓存文件</td><td>512 MB</td><td>512 MB</td><td>512 MB</td><td>默认 5 GB，可申请调整</td></tr></tbody></table><p>来源：<a href="https://developers.cloudflare.com/cache/concepts/default-cache-behavior/#upload-limits" target="_blank" rel="noreferrer">官方上传和缓存大小限制</a>。域名后台也可能配置更低上传上限。</p><p>100 MB 是<strong>一次请求上传体积</strong>，不是每月总流量。应用支持分块上传时，可以将大文件分成多个请求；不能保证所有 NAS/WebDAV 应用默认都支持。512 MB 是<strong>缓存限制</strong>，不能误写成“下载超过 512 MB 一律失败”。超时、业务服务配置和服务条款还会影响实际结果。</p><h2 id="带宽、视频与网盘" tabindex="-1">带宽、视频与网盘 <a class="header-anchor" href="#带宽、视频与网盘" aria-label="Permalink to &quot;带宽、视频与网盘&quot;">​</a></h2><p>官方 Tunnel 文档没有给出一个适用于所有免费命名隧道的固定 Mbps 或月度 GB 保证，不应宣传为“无限带宽且不限用途”。国内速度受运营商、跨境线路、Cloudflare 边缘和你自己的上行带宽影响，加速镜像下载快不代表隧道访问快。</p><p><a href="https://developers.cloudflare.com/cloudflare-one/faq/cloudflare-tunnels-faq/#large-file-and-streaming-traffic-through-tunnel" target="_blank" rel="noreferrer">官方 Tunnel FAQ</a> 明确区分：</p><ul><li>公网域名路由经过反向代理，Free/Pro/Business 分发视频和其他大文件须使用对应的特定付费服务，受 <a href="https://www.cloudflare.com/service-specific-terms-application-services/#content-delivery-network-free-pro-or-business" target="_blank" rel="noreferrer">CDN 服务条款</a> 约束。</li><li>私网路由不把应用发布到互联网，上述内容分发限制不适用，但需要 Cloudflare One Client/Mesh/WAN 等相应接入方式。它不是给普通公网用户的下载链接。</li></ul><p>NAS 管理面板、普通网站和小请求 API 是常见使用场景；公网影音库播放、网盘大文件分发不能直接当成免费不限量用途。</p><h2 id="access-与-tunnel-不同" tabindex="-1">Access 与 Tunnel 不同 <a class="header-anchor" href="#access-与-tunnel-不同" aria-label="Permalink to &quot;Access 与 Tunnel 不同&quot;">​</a></h2><p>Tunnel 提供连接；Access 提供访客身份验证。Tunnel 免费不代表 Access、Stream、Load Balancing 等所有附加产品都免费。若启用 Access，应另核对 <a href="https://www.cloudflare.com/plans/zero-trust-services/" target="_blank" rel="noreferrer">Cloudflare One 套餐</a>，不要将 Access 席位数理解为 Tunnel 公网网站的访客上限。</p><h2 id="实际使用情况" tabindex="-1">实际使用情况 <a class="header-anchor" href="#实际使用情况" aria-label="Permalink to &quot;实际使用情况&quot;">​</a></h2><p>项目已完成的本地/安装包验证见 <a href="/cloudflare-tunnel-manager/guide/verification">验证记录</a>。截至本次核对，<strong>没有</strong>用真实 Cloudflare 凭据完成 v1.8.1 的公网隧道、连续在线压力、国内吞吐或大文件上传测试；不发布虚构测速和“所有功能保证可用”的结论。</p><p>本次官方资料来自 <a href="https://github.com/cloudflare/cloudflare-docs" target="_blank" rel="noreferrer">Cloudflare 文档源码仓库</a>，对应页面见上方链接。官方内容会更新，部署前请再次核对你的套餐与条款。</p>',20)])])}const p=t(d,[["render",n]]);export{f as __pageData,p as default};
